import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS,T,en,DUR,interpolate,clamp,Easing,FONT,Textura,Profundidad,Brillo,Camara,Paso,Entrar,Recorrido,seguir,tono} from './kit';

export const SUBS={arriba:230,acento:'#E7FF00'};
const A=[0,7,23,39,57,67,85,97,106,121,138,151,160].map(T);
const L='#E7FF00',V='#a89aff',BLUE='#659bdb';
const ease=Easing.inOut(Easing.cubic);
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:ease});
const phase=(s:number,i:number)=>q(s,A[i],i===12?DUR:A[i+1]);
const pulse=(s:number,t:number)=>s<t?0:Math.sin(Math.min(1,(s-t)/.6)*Math.PI);
const jump=(s:number,t:number)=>s<t?0:Math.max(0,Math.sin(Math.min(1,(s-t)/.8)*Math.PI));
const Label:React.FC<{x:number;y:number;children:React.ReactNode;color?:string;size?:number}>=({x,y,children,color=L,size=42})=><g transform={`translate(${x} ${y})`}><rect x={-195} y={-43} width={390} height={86} rx={18} fill='#111b32' stroke={color} strokeWidth={3}/><text textAnchor='middle' y={15} fontSize={size} fontWeight={800} fill={color}>{children}</text></g>;

const Defs=()=> <defs>
 <linearGradient id='skin' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#e6b18c'/><stop offset='.6' stopColor='#c88763'/><stop offset='1' stopColor='#935137'/></linearGradient>
 <linearGradient id='cloth' x1='0' y1='0' x2='.4' y2='1'><stop stopColor='#9cbddd'/><stop offset='.4' stopColor='#577ca7'/><stop offset='1' stopColor='#264667'/></linearGradient>
 <radialGradient id='brain'><stop stopColor='#e9c6dc'/><stop offset='.7' stopColor='#bc86b5'/><stop offset='1' stopColor='#744b83'/></radialGradient>
 <linearGradient id='muscle' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#ffb5a5'/><stop offset='.4' stopColor='#d96064'/><stop offset='1' stopColor='#7f283e'/></linearGradient>
 <radialGradient id='light'><stop stopColor='#ffdfa0' stopOpacity='.5'/><stop offset='1' stopColor='#ffcc72' stopOpacity='0'/></radialGradient>
 </defs>;

// Adulto acostado de perfil, con ojos cerrados o mirada despierta; el pie se descubre al patear.
const Sleeper:React.FC<{s:number;j?:number;awake?:boolean;other?:boolean}>=({s,j=0,awake=false,other=false})=>{
 const breathe=Math.sin(s*2.3)*6;
 return <g>
  <ellipse cx={0} cy={235} rx={450} ry={40} fill='#030d1c' opacity='.65'/>
  <rect x={-445} y={72} width={890} height={120} rx={18} fill='#665347'/><rect x={-440} y={37} width={880} height={110} rx={32} fill='#d5d1c7'/>
  <path d='M-438 140H438M-420 198V270M420 198V270' stroke='#332e30' strokeWidth={20}/>
  <rect x={-442} y={-105} width={200} height={168} rx={55} fill='#efe4cc' transform='rotate(-8 -340 -20)'/>
  <g transform={`translate(0 ${-j*105}) rotate(${-j*4})`}>
   <path d='M-280 -30Q-180 -80 -70 -50L105 -10L95 90L-238 84Z' fill='#658da0' stroke='#b9d4d2' strokeWidth={4}/>
   <path d='M-240 -48L-168 15L-90 0' stroke='url(#skin)' strokeWidth={40} fill='none' strokeLinecap='round'/><circle cx={-83} cy={0} r={23} fill='url(#skin)'/>
   <path d={`M-80 30Q90 ${-35-breathe-j*85} 240 -2L390 ${25-j*100}L433 127H-130Z`} fill='url(#cloth)' stroke='#aec6de' strokeWidth={5}/>
   {[-60,20,110,205,300].map((x,i)=><path key={i} d={`M${x} 22Q${x+10} ${75+breathe+i*5} ${x+45} 133`} stroke='#c6d5e3' strokeOpacity='.22' strokeWidth={5} fill='none'/>)}
   <g transform={`translate(-310 ${-38-j*12}) rotate(${-j*10})`}>
    <ellipse rx={63} ry={72} fill='url(#skin)' stroke='#f0c3a1' strokeWidth={3}/>
    <path d='M-57 -5Q-80 -85 -12 -86Q55 -88 61 -35L36 -41L18 -57L-6 -54L-30 -16Z' fill='#3b302e'/>
    <ellipse cx={-52} cy={12} rx={12} ry={19} fill='#d79572'/>
    {awake?<><ellipse cx={-11} cy={2} rx={9} ry={12} fill='#121c27'/><circle cx={-8} cy={-2} r={3} fill='white'/><ellipse cx={27} cy={-1} rx={8} ry={12} fill='#121c27'/><circle cx={30} cy={-5} r={3} fill='white'/></>:<><path d='M-21 2Q-12 9 -2 1M19 -1Q29 5 38 -4' stroke='#3b302e' strokeWidth={5} fill='none' strokeLinecap='round'/></>}
    <path d='M13 5L20 22L9 24M-1 43Q15 48 30 39' stroke='#915337' strokeWidth={4} fill='none' strokeLinecap='round'/>
    <path d='M-40 42Q-10 79 41 39' stroke='#594139' strokeOpacity='.45' strokeWidth={9} fill='none'/>
   </g>
   <path d={`M300 23L${365+j*40} ${-j*165}L${405+j*35} ${-j*180}`} stroke='url(#skin)' strokeWidth={35} fill='none' strokeLinecap='round'/>
  </g>
  {other&&<g transform='translate(215 -205) rotate(12)'><ellipse rx={57} ry={69} fill='#a3654b' stroke='#e4b999' strokeWidth={3}/><path d='M-56 -2Q-70 -83 -5 -79Q62 -76 60 -5L31 -35L-20 -30Z' fill='#25232c'/><ellipse cx={-18} cy={8} rx={8} ry={11} fill='#121621'/><ellipse cx={20} cy={8} rx={8} ry={11} fill='#121621'/><circle cx={-16} cy={5} r={3} fill='white'/><circle cx={22} cy={5} r={3} fill='white'/><path d='M-21 38H21' stroke='#442e29' strokeWidth={5}/><path d='M-65 75Q0 30 65 75L100 170H-100Z' fill='#a386a2'/></g>}
 </g>;
};

const Room:React.FC<{s:number;j?:number;other?:boolean;awake?:boolean}>=({s,j=0,other=false,awake=false})=><g>
 <path d='M0 1490H1080V1920H0Z' fill='#253b50'/>{[0,1,2,3,4].map(i=><path key={i} d={`M${i*260-140} 1490L${i*400-280} 1920M0 ${1540+i*72}H1080`} stroke='#426075' strokeOpacity='.45' strokeWidth={3}/>)}
 <rect x={50} y={460} width={280} height={440} rx={8} fill='#10263c' stroke='#426480' strokeWidth={15}/><path d='M190 460V900M50 670H330' stroke='#426480' strokeWidth={9}/><circle cx={260} cy={535} r={42} fill='#e5e7c2'/>
 <path d={`M25 445Q${90+Math.sin(s)*12} 650 24 980M360 445Q${300+Math.sin(s)*12} 650 355 980`} stroke='#547692' strokeWidth={40} fill='none'/>
 <ellipse cx={865} cy={1000} rx={300} ry={420} fill='url(#light)'/>
 <rect x={810} y={1190} width={210} height={180} rx={12} fill='#5a4b42'/><path d='M860 1190V920M800 920L830 810H900L930 920Z' stroke='#e2b46d' strokeWidth={10} fill='#e4be7e'/><circle cx={863} cy={902} r={17} fill='#ffe5b2'/>
 <g transform='translate(540 1190)'><Sleeper s={s} j={j} awake={awake} other={other}/></g>
 </g>;

const Brain:React.FC<{s:number;house?:boolean;off?:number}>=({s,house=false,off=0})=><g transform='translate(540 1030)'>
 <path d='M-60 265L-15 385L68 385L50 270' fill='#c798b5' stroke='#745780' strokeWidth={8}/>
 <path d='M-310 83Q-395 30 -362 -60Q-408 -160 -312 -220Q-300 -322 -180 -315Q-90 -398 14 -342Q116 -390 192 -303Q305 -320 328 -215Q425 -170 365 -68Q410 35 324 85Q315 220 166 227Q78 302 -18 237Q-114 286 -202 215Q-320 218 -310 83Z' fill='url(#brain)' stroke='#efd3e7' strokeWidth={9}/>
 {[-240,-120,0,120,240].map((x,i)=><path key={i} d={`M${x} -230Q${x-95} -155 ${x+12} -80Q${x+80} -5 ${x-15} 70Q${x-65} 160 ${x+28} 210`} fill='none' stroke='#754d83' strokeWidth={11} strokeLinecap='round' opacity='.6'/>)}
 <path d='M0 -300Q-30 -120 10 40Q35 190 0 235' stroke='#74457f' strokeWidth={8} fill='none'/>
 {house&&<g><path d='M-255 -110L0 -285L255 -110V175H-255Z' fill='#312d56' stroke='#d3a3c7' strokeWidth={7}/><path d='M-270 -100L0 -300L270 -100' fill='none' stroke='#f0bfcb' strokeWidth={14}/>{[0,1,2,3,4,5].map(i=>{const k=q(off,i/7,(i+1)/7),x=-183+(i%3)*150,y=-72+Math.floor(i/3)*135;return <g key={i}><rect x={x} y={y} width={105} height={94} rx={8} fill={k>.5?'#302b57':'#ffe291'} stroke='#ae87bc' strokeWidth={5}/><path d={`M${x+52} ${y}V${y+94}M${x} ${y+47}H${x+105}`} stroke='#71557e' strokeWidth={5}/>{k<1&&<rect x={x+7} y={y+7} width={91} height={80*(1-k)} fill='#fff1bd' opacity='.5'/>}</g>})}</g>}
 </g>;

const Spark:React.FC<{x:number;y:number;ang?:number;k?:number}>=({x,y,ang=0,k=1})=><g transform={`translate(${x} ${y}) rotate(${ang}) scale(${k})`}><circle r={43} fill={L} opacity='.12'/><circle r={27} fill={L} opacity='.22'/><path d='M-9 -34L-24 5H-3L-10 35L25 -10H5L12 -34Z' fill={L} stroke='#fbffd5' strokeWidth={4}/></g>;
const Switches:React.FC<{s:number;calm?:boolean}>=({s,calm=false})=>{
 const k1=calm?1:q(s,en('despierto'),en('duerme'));
 const k2=calm?1:q(s,en('duerme'),A[6]+.2);
 return <g>{[0,1].map(i=>{const x=300+i*480,k=i?k2:k1;return <g key={i} transform={`translate(${x} 1020)`}>
 <rect x={-180} y={-245} width={360} height={535} rx={38} fill='#342e55' stroke={i?V:L} strokeWidth={7}/><path d='M0 -115V140' stroke='#0c172d' strokeWidth={50} strokeLinecap='round'/><path d={`M-85 ${-100+k*220}H85`} stroke={i?V:L} strokeWidth={45} strokeLinecap='round'/><circle cy={-100+k*220} r={42} fill={i?'#c9bdff':'#f3ff89'}/><text y={225} textAnchor='middle' fill={i?V:L} fontSize={34} fontWeight={800}>{i?'DORMIDO':'DESPIERTO'}</text>
 </g>})}<path d={`M330 ${920+k1*220}Q540 1370 750 ${920+k2*220}`} stroke={L} strokeDasharray='12 18' strokeDashoffset={-s*95} strokeWidth={8} fill='none'/>
 {calm&&<g transform={`translate(${320+440*q(s,en('cambiando'),A[12])} 1440)`}><rect x={-130} y={-36} width={260} height={72} rx={15} fill='#d9d5f0'/><text textAnchor='middle' y={12} fill='#302d50' fontSize={30} fontWeight={800}>TURNO</text></g>}
 </g>;
};

const Muscle:React.FC<{s:number;contract?:number}>=({s,contract=0})=>{
 const d=contract;
 return <g transform={`translate(540 1030) rotate(${-8-d*20})`}>
 <path d='M-90 -440L100 -435L86 -70Q160 140 95 440L-95 440Q-20 150 -90 -45Z' fill='#deb293' fillOpacity='.33' stroke='#edc8ad' strokeWidth={7}/>
 <path d={`M-20 -410L-5 ${-110+d*70}L28 100L4 425`} stroke='#eadfce' strokeWidth={40} fill='none' strokeLinecap='round'/>
 <path d={`M-10 ${-350+d*80}C${-160-d*40} -180 ${-135-d*55} ${-15-d*30} -8 45C${115+d*55} -65 ${135+d*35} -190 -10 ${-350+d*80}Z`} fill='url(#muscle)' stroke='#ffc2b5' strokeWidth={5}/>
 {[0,1,2,3,4,5,6].map(i=><path key={i} d={`M-8 ${-325+d*80}Q${-115+i*34+Math.sin(s*3+i)*14} ${-140+d*30} -8 25`} fill='none' stroke={i%2?'#fa9e96':'#a94451'} strokeWidth={8}/>) }
 <path d='M-10 45L28 100L4 425' stroke='#f2e1be' strokeWidth={12} fill='none'/>
 <path d={`M4 425L${110+d*140} ${455-d*180}`} stroke='#deb293' strokeWidth={65} fill='none' strokeLinecap='round'/>
 </g>;
};

const Falling:React.FC<{s:number;p:number;step?:boolean}>=({s,p,step=false})=><g>
 {Array.from({length:28}).map((_,i)=><circle key={i} cx={(i*181)%1080} cy={(i*113+s*65)%1920} r={i%3+2} fill='#b9cce1' opacity='.55'/>)}
 <path d={`M70 1090H${500-220*p}V${1260+220*p}H${880-220*p}`} fill='none' stroke='#7794b0' strokeWidth={55} strokeLinejoin='round' opacity={1-p*.85}/>
 <g transform={`translate(${420+p*190} ${820+p*540}) rotate(${p*62})`}>
 <ellipse cx={0} cy={-150} rx={50} ry={63} fill='url(#skin)'/><path d='M-48 -162Q-60 -225 10 -218Q58 -207 48 -172' fill='#3b302e'/>
 <path d='M-38 -88Q0 -110 50 -85L70 90H-50Z' fill='#658da0' stroke='#aacbd4' strokeWidth={4}/>
 <path d={`M-32 -65L${-90-p*65} ${-55-p*110}M42 -60L${105+p*60} ${-25-p*135}`} stroke='url(#skin)' strokeWidth={28} strokeLinecap='round' fill='none'/>
 <path d={`M-22 90L-70 230L${-25-p*90} 310M40 90L110 175L${140+p*65} 275`} stroke='#56789a' strokeWidth={46} strokeLinecap='round' fill='none'/>
 <path d={`M${-25-p*90} 310H${15-p*90}M${140+p*65} 275H${180+p*65}`} stroke='url(#skin)' strokeWidth={29} strokeLinecap='round'/>
 </g>
 {step&&<path d={`M520 1240H${850-p*300}V1320H520Z`} fill='#7794b0' opacity={1-p}/>} </g>;

const NERVE:[number,number][]=[[460,610],[620,780],[430,1010],[580,1240],[470,1500]];
const Scene:React.FC<{i:number}>=({i})=>{
 const {s}=useS();const p=phase(s,i);
 const view=(content:React.ReactNode)=> <svg width={1080} height={1920}><Defs/>{content}</svg>;
 let g:React.ReactNode;
 if(i===0)g=<Room s={s} j={jump(s,en('brinco'))} awake={s>en('brinco')}/>;
 else if(i===1){const c=en('caes'),r=en('salto');g=s<c?<Room s={s}/>:s<r?<Falling s={s} p={q(s,c,r)} step/>:<Room s={s} j={jump(s,r)} awake/>;}
 else if(i===2)g=<><Label x={540} y={620} size={34}>SACUDIDA DEL SUEÑO</Label>{Array.from({length:10}).map((_,j)=>{
  const k=j<7?Math.max(0,Math.sin((s-A[2])*4-j*.5)):0;
  return <g key={j} transform={`translate(${300+(j%2)*480} ${820+Math.floor(j/2)*170}) scale(.43)`}><Sleeper s={s+j} j={k*.7}/></g>;
 })}</>;
 else if(i===3)g=<Entrar t={A[3]} dur={Math.min(.9,(A[4]-A[3])*.25)} x={540} y={1030} zoom={4} fuera={<Brain s={s}/>} dentro={<><Brain s={s} house off={q(s,en('apagando'),A[4])}/><Label x={540} y={1510} color={V}>UNA TEORÍA</Label></>}/>;
 else if(i===4)g=<><Muscle s={s} contract={1-q(s,A[4],en('blando'))}/><Label x={540} y={1600} color='#ffae9f'>SE AFLOJAN</Label></>;
 else if(i===5)g=<><Brain s={s}/><g opacity='.95'><Switches s={s}/></g><Spark x={540+Math.sin(p*Math.PI)*160} y={1340-p*130} k={pulse(s,en('ritmo'))}/></>;
 else if(i===6){const start=en('descarga'),end=A[7];g=<><Brain s={s}/><path d='M460 610C690 770 330 900 430 1010S680 1300 470 1500' stroke='#d8bb94' strokeWidth={65} fill='none'/><path d='M460 610C690 770 330 900 430 1010S680 1300 470 1500' stroke='#b58f63' strokeWidth={11} fill='none' strokeDasharray='20 18'/><Recorrido puntos={NERVE} t0={start} t1={end} color={L} render={(x,y,ang)=><Spark x={x} y={y} ang={ang}/>}/></>;}
 else if(i===7){const k=jump(s,en('contraen'));g=<><Muscle s={s} contract={k}/><Spark x={500} y={940-k*150} k={1-k*.5}/>{[0,1,2].map(j=><path key={j} d={`M${730+j*50} ${1040-j*80}L${770+j*50} ${1000-j*80}`} stroke={L} strokeWidth={8} opacity={k}/> )}</>;}
 else if(i===8){const idea=q(s,en('razón'),en('caíste'));g=<><g transform='translate(-100 150) scale(.7)'><Brain s={s}/></g><g transform={`translate(0 ${-70+p*80})`}><path d='M280 650Q180 600 260 470Q340 350 470 420Q650 330 800 470Q980 540 870 750Q830 860 620 820Q390 890 280 750Z' fill='#18253b' stroke='#c7c1ec' strokeWidth={9}/><circle cx={290} cy={900} r={35} fill='#c7c1ec'/><circle cx={265} cy={960} r={20} fill='#c7c1ec'/><g transform='translate(330 180) scale(.46)'><Falling s={s} p={p}/></g><text x={790} y={680} fontSize={140} fill={L} fontWeight={800}>{idea>.5?'!':'?'}</text></g></>;}
 else if(i===9)g=<Falling s={s} p={q(s,A[9],A[10])} step/>;
 else if(i===10){const ct=en('café'),st=en('estrés'),ca=en('cansancio');g=<>
 <path d='M0 1390H1080V1650H0Z' fill='#635046'/>{[0,1,2,3,4].map(j=><path key={j} d={`M0 ${1410+j*50}Q500 ${1390+j*50} 1080 ${1425+j*50}`} stroke='#997863' strokeWidth={4} fill='none'/>)}
 <g transform={`translate(${250+p*65} 1220) rotate(${Math.sin(s*3)*3})`}><path d='M-100 -150H100L80 160H-80Z' fill='#d8e1dd' stroke='#fff4db' strokeWidth={5}/><ellipse cy={-150} rx={100} ry={25} fill='#553929'/><path d='M100 -95Q240 -95 110 65' stroke='#d8e1dd' strokeWidth={28} fill='none'/>{[0,1,2].map(j=><path key={j} d={`M${-50+j*50} -200Q${-80+j*50+Math.sin(s*2+j)*40} -280 ${-40+j*50} -360`} stroke='#f1e0c2' strokeWidth={9} fill='none' opacity='.5'/>)}<Spark x={0} y={-420} k={q(s,ct,ct+.4)}/></g>
 <g transform={`translate(${740-p*45} ${850+Math.sin(s*2)*15}) rotate(${Math.sin(s*4)*4})`}><circle r={160} fill='#17243b' stroke='#c0d3db' strokeWidth={15}/><path d='M0 -100V0H95' stroke={V} strokeWidth={14} strokeLinecap='round' fill='none'/>{Array.from({length:12}).map((_,j)=><path key={j} d='M0 -128V-140' transform={`rotate(${j*30})`} stroke='#c7d9e8' strokeWidth={6}/>)}<Spark x={0} y={-230} k={q(s,ca,ca+.4)}/></g>
 {[0,1,2,3].map(j=><g key={j} transform={`translate(${740+Math.sin(s+j)*12} ${1360-j*40}) rotate(${j%2?7:-5})`}><rect x={-160} y={-80} width={320} height={110} fill={j%2?'#d8d1c4':'#eee8d5'}/>{[0,1,2].map(k=><path key={k} d={`M-120 ${-55+k*25}H100`} stroke='#a6a195' strokeWidth={5}/>)}</g>)}<Spark x={730} y={1120} k={q(s,st,st+.4)}/>
 </>;}
 else if(i===11)g=<g transform='translate(540 1000) scale(.9) translate(-540 -1000)'><Brain s={s}/><Switches s={s} calm/><Label x={540} y={640} color={V}>SUELE SER INOFENSIVO</Label></g>;
 else g=<Room s={s} j={jump(s,en('pateando'))} awake={false} other/>;
 let stops=[{t:A[i],x:540,y:1040,zoom:.94},{t:i===12?DUR:A[i+1],x:540+Math.sin(i*1.8)*70,y:1020,zoom:1.10}];
 if(i===6)stops=seguir(NERVE,en('descarga'),A[7],1.45);
 return <Camara paradas={stops}>{view(g)}</Camara>;
};

export const Escena:React.FC=()=>{
 const {s}=useS();let i=0;for(let j=1;j<A.length;j++)if(s>=A[j])i=j;
 const bg=tono(s,[A[0],A[3],A[4],A[5],A[7],A[8],A[10],A[12]],['#11263d','#322c52','#442335','#302b50','#4c2837','#0b1425','#342c30','#11263d']);
 let body:React.ReactNode=<Scene i={i}/>;
 const tr:[number,'forma'|'entrar'|'barrido'|'alejar'][]=[[1,'forma'],[3,'entrar'],[4,'barrido'],[9,'forma'],[10,'barrido'],[12,'alejar']];
 for(const [n,tipo]of tr)if(s>=A[n]-.2&&s<A[n]+.35)body=<Paso t={A[n]} tipo={tipo} x={540} y={1030} dur={.55} antes={<Scene i={n-1}/>} despues={<Scene i={n}/>}/>;
 return <AbsoluteFill style={{fontFamily:FONT,background:bg}}><Textura tipo={i>=3&&i<=8?'celulas':'fibra'} base={`radial-gradient(ellipse at 45% 52%,${bg},#071020)`} linea={i>=3&&i<=8?'#846987':'#36536a'} luz='rgba(179,198,222,.07)' opacidad={.75} semilla={8}/><Brillo x={530} y={1050} r={470} color={i>=3&&i<=8?'rgba(199,153,213,.20)':'rgba(255,214,148,.14)'}/>{body}<Profundidad color='rgba(6,15,29,.22)' lejos='rgba(200,218,235,.10)' manchas={3} semilla={14} deriva={.45}/></AbsoluteFill>;
};

// Cada sonido corresponde a una acción del guion; volumen de mezcla definido en el motor.
const cues:[string,number,string,number][]=[
 ['Ese',1,'whoosh_01',0],['brinco',1,'pop_03',0],['dormido',1,'whoosh_02',0],['explicación',1,'ding_01',0],
